content.content:
/// whatever the catalog charged on their signup day for the rest of their
/// tenure, no matter how many times the catalog price rises after that.
/// `renewalCharge` (lib/renewal-charge.ts) reads THIS instead of the live
/// `plan.priceCents` / `gamePlan.priceCents` when it is set.
///
/// NULL = pre-existing row that predates this column (backfilled once at
/// launch to each server's then-current rate — see the migration script),
/// or a free/admin-granted server that was never sold a real price to
/// freeze. Falls back to the live catalog price in either case, which for
/// a backfilled row is a no-op (the backfill already equals that price)
/// and for a free server is correct (nothing to protect).
///
/// Cleared (set back to null) by a plan/tier CHANGE (resizeServer,
/// changeGameTier) — switching to a different plan is choosing that
/// plan's current terms, not carrying the old plan's frozen rate onto a
/// plan the customer never actually bought at that price. The change
/// itself then re-freezes at the NEW plan's current price, same as any
/// other fresh order.
grandfatheredRenewalCents Int?
/// RETENTION OFFER (2026-09-19). A ONE-TIME, TEMPORARY percent-off applied to
/// the very NEXT renewal charge only — `renewalCharge` (lib/renewal-charge.ts)
/// reads it alongside `grandfatheredRenewalCents` but for a different purpose:
/// that field freezes a PERMANENT per-month rate, this one shaves a PERCENT off
/// exactly one upcoming renewal EVENT (whatever it charges, term included) and
/// is then CLEARED — set back to null in the very same transaction that commits
/// the discounted renewal (worker/billing.ts `commitRenewal`, and the manual
/// "Renew now" action in lib/actions.ts), so it can never silently reapply to
/// the period after that.
///
/// Set by `claimRetentionOffer` (lib/actions-server-lifecycle.ts) when a
/// customer accepts the "stay and save" interstitial shown on cancel-plan.
/// Whether an account may claim this AT ALL — once, ever, on any one of its
/// servers — is enforced through the real Coupon/CouponRedemption engine
/// (code STAY50, the `@@unique([couponId,userId])` constraint) rather than a
/// second flag on this row; this field only ever carries the discount PERCENT
/// itself through to the renewal formula once that claim has already
/// succeeded.
///
/// NULL = no discount pending (the overwhelmingly common case). Never negative
/// and never > 100 — `claimRetentionOffer` only ever writes 50.
pendingRenewalDiscountPercent Int?

1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { ServerStatus } from "@prisma/client";
5	import { PageHeader, StatusDot, Badge, fmtMoney, fmtBytes } from "@/components/ui/primitives";
6	import { MeterBar } from "@/components/ui/charts";
7	import { monthlyCents } from "@/lib/admin-metrics";
8	import { SuspendServerButton, ReconcileServerButton } from "@/components/AdminControls";
9	import { RebootServerButton } from "@/components/admin/ServerAdminActions";
10	import { ServerFleetTable, type FleetColumn, type FleetRow } from "@/components/admin/ServerFleetTable";
11	import { AutoRefresh } from "@/components/AutoRefresh";
12	import { pveForNode, listVms } from "@/lib/proxmox";
13	import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
14	import { CountryFlag } from "@/components/ui/CountryFlag";
15	import { resolveServerLifetimeSpendCents } from "@/lib/server-spend";
16	import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
17	
18	export const dynamic = "force-dynamic";
19	
20	const STATUSES = Object.values(ServerStatus);
21	const TRANSITIONAL: ServerStatus[] = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];
22	
23	/** Servers renewing within this many days surface in the "expiring soon" alert. */
24	const EXPIRING_SOON_DAYS = 5;
25	
26	/** Archive-backed filters (ServerArchive.reason values), distinct from the live
27	 *  ServerStatus enum above — see prisma schema's ServerArchive doc comment for
28	 *  how `reason` is derived. "Deleted" folds REMOVED in with DELETED: the admin
29	 *  request behind this filter is "show me servers that are gone", and the
30	 *  REMOVED/DELETED distinction is a finer one than that ask needs at a glance. */
31	const ARCHIVE_FILTERS: Record<string, { label: string; reasons: string[] }> = {
32	  CANCELLED: { label: "cancelled", reasons: ["CANCELLED"] },
33	  EXPIRED: { label: "expired", reasons: ["EXPIRED"] },
34	  DELETED: { label: "deleted", reasons: ["REMOVED", "DELETED"] },
35	};
36	
37	/** 24x24 cover thumbnail for a game family, or the game's glyph on a plain
38	 *  background when no poster art exists yet (e.g. a freshly-scaffolded
39	 *  family) — mirrors the "no poster 404s" fallback lib/games.ts itself
40	 *  documents for GAME_ART_SLUG. */
41	function GameCover({ family }: { family: string }) {
42	  const art = GAME_ART_SLUG[family as GameFamily];
43	  const display = GAME_DISPLAY[family as GameFamily];
44	  if (art?.poster) {
45	    return (
46	      <img
47	        src={`/games/art/${art.poster}_poster.jpg`}
48	        alt=""
49	        width={28}
50	        height={28}
51	        className="h-7 w-7 shrink-0 rounded-md object-cover"
52	      />
53	    );
54	  }
55	  return (
56	    <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.06] text-sm">
57	      {display?.glyph ?? "🎮"}
58	    </span>
59	  );
60	}
61	
62	/** Plain server-rack icon for a VPS, same stroke style as the sidebar's own
63	 *  "server" glyph (components/portal/Shell.tsx) so the fleet table matches
64	 *  the rest of the admin chrome. */
