66	  return (
67	    <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-white/[0.06] text-slate-300">
68	      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
69	        <rect x="3" y="4" width="18" height="7" rx="2" />
70	        <rect x="3" y="13" width="18" height="7" rx="2" />
71	        <circle cx="7.5" cy="7.5" r="0.8" fill="currentColor" />
72	        <circle cx="7.5" cy="16.5" r="0.8" fill="currentColor" />
73	      </svg>
