87	function RegionCell({ region }: { region: string | null }) {
88	  if (!region) return <span className="text-xs text-slate-500">—</span>;
89	  const code = REGION_COUNTRY[region];
90	  return (
91	    <span className="flex items-center gap-1.5 text-xs text-slate-400">
