98	export default async function AdminServers({
99	  searchParams,
100	}: {
101	  searchParams: Promise<{ status?: string }>;
102	}) {
103	  await requireArea("fleet");
104	  const { status } = await searchParams;
105	  const archiveFilter = status && ARCHIVE_FILTERS[status] ? status : undefined;
106	  const statusFilter = !archiveFilter && STATUSES.includes(status as ServerStatus) ? (status as ServerStatus) : undefined;
107	
108	  // ── Archive view: a churned server has no live VM, no resources, no actions
109	  //    — a different, simpler table, not the live fleet query below at all. ──
110	  if (archiveFilter) {
111	    const filter = ARCHIVE_FILTERS[archiveFilter];
112	    const [archived, liveCounts, archiveCounts] = await Promise.all([
113	      db.serverArchive.findMany({ where: { reason: { in: filter.reasons } }, orderBy: { deletedAt: "desc" } }),
114	      db.server.count(),
115	      db.serverArchive.groupBy({ by: ["reason"], _count: true }),
116	    ]);
117	    const archiveCountFor = (reasons: string[]) =>
118	      archiveCounts.filter((c) => reasons.includes(c.reason)).reduce((n, c) => n + c._count, 0);
119	
120	    const columns: FleetColumn[] = [
121	      { header: "Hostname" },
122	      { header: "Owner" },
123	      { header: "Type" },
124	      { header: "Service" },
125	      { header: "Node" },
126	      { header: "Region" },
127	      { header: "Total spent" },
128	      { header: "Provisioned" },
129	      { header: "Reason" },
130	      { header: "Removed" },
131	    ];
132	    const rows: FleetRow[] = archived.map((a) => ({
133	      id: a.id,
134	      search: [a.hostname, a.userEmail, a.serviceName, a.nodeName].filter(Boolean).join(" ").toLowerCase(),
135	      cells: [
136	        <span key="h" className="font-medium text-slate-300">{a.hostname}</span>,
137	        a.userId ? (
138	          <Link key="o" href={`/admin/users/${a.userId}`} className="text-slate-300 hover:text-brand-300">
139	            {a.userEmail}
140	          </Link>
141	        ) : (
142	          <span key="o" className="text-slate-500">{a.userEmail || "—"}</span>
143	        ),
144	        <ServiceType key="t" gameFamily={a.gameFamily} />,
145	        <span key="p" className="text-xs">{a.serviceName}</span>,
146	        <span key="n" className="text-xs text-slate-400">{a.nodeName ?? "—"}</span>,
147	        <RegionCell key="r" region={a.region} />,
148	        <span key="sp" className="text-xs">{a.totalSpentCents > 0 ? fmtMoney(a.totalSpentCents) : <span className="text-slate-600">—</span>}</span>,
149	        <span key="prov" className="text-xs text-slate-400">{a.provisionedAt.toISOString().slice(0, 10)}</span>,
150	        <Badge key="reason" tone={a.reason === "CANCELLED" ? "slate" : a.reason === "EXPIRED" ? "amber" : "red"}>
151	          {a.reason.toLowerCase()}
152	        </Badge>,
153	        <span key="del" className="text-xs text-slate-400" title={a.deletedAt.toISOString()}>
154	          {a.deletedAt.toISOString().slice(0, 10)}
155	        </span>,
156	      ],
157	    }));
158	
159	    return (
160	      <div className="space-y-6">
161	        <PageHeader title="Server fleet" sub={`${archived.length} ${filter.label} server${archived.length === 1 ? "" : "s"}.`} />
162	        <StatusChips liveTotal={liveCounts} archiveCountFor={archiveCountFor} active={archiveFilter} liveActive={undefined} />
163	        <ServerFleetTable columns={columns} rows={rows} minWidth={1400} empty={`No ${filter.label} servers.`} />
164	      </div>
165	    );
166	  }
167	
168	  const [servers, counts, archiveCounts] = await Promise.all([
169	    db.server.findMany({
170	      where: statusFilter ? { status: statusFilter } : undefined,
171	      include: {
172	        user: { select: { id: true, email: true, name: true } },
173	        plan: { select: { name: true, priceCents: true } },
174	        gamePlan: { select: { name: true, priceCents: true, termMonths: true, gameFamily: true } },
175	        node: { select: { id: true, name: true, region: true, publicIp: true, apiUrl: true, pveNode: true, tokenId: true, tokenSecret: true } },
176	      },
177	      orderBy: { createdAt: "desc" },
178	    }),
179	    db.server.groupBy({ by: ["status"], _count: true }),
180	    db.serverArchive.groupBy({ by: ["reason"], _count: true }),
181	  ]);
182	
183	  const countByStatus = new Map(counts.map((c) => [c.status, c._count]));
184	  const total = counts.reduce((n, c) => n + c._count, 0);
185	  const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));
186	  const archiveCountFor = (reasons: string[]) =>
187	    archiveCounts.filter((c) => reasons.includes(c.reason)).reduce((n, c) => n + c._count, 0);
188	
189	  // Real, historical lifetime revenue per server (order + renewals + add-ons,
190	  // net of refunds) — see lib/server-spend.ts for exactly what "real" means
191	  // here and the one verified historical gap it corrects for. Fleet-wide at
192	  // once: 33 servers today, cheap regardless of the status filter above.
193	  const spendByServerId = await resolveServerLifetimeSpendCents(
194	    servers.map((s) => ({ id: s.id, hostname: s.hostname, userId: s.userId, createdAt: s.createdAt })),
195	  );
196	
197	  // Live resource metrics, one Proxmox call PER NODE (not per server) — /qemu
198	  // on a node returns every VM's current cpu/mem in one shot, so this stays
199	  // cheap regardless of how many servers are in the fleet. A node's API being
200	  // slow/unreachable only blanks out ITS OWN servers' metrics column, same
201	  // "one node down doesn't take the others with it" discipline as the
202	  // Infrastructure page.
203	  const nodesById = new Map(servers.map((s) => s.node).filter((n): n is NonNullable<typeof n> => !!n).map((n) => [n.id, n]));
204	  const liveByNode = new Map(
205	    await Promise.all(
206	      Array.from(nodesById.values()).map(async (n) => {
207	        try {
208	          const vms = await listVms(pveForNode(n));
209	          const byVmid = new Map(vms.map((v: any) => [v.vmid, v]));
210	          return [n.id, byVmid] as const;
211	        } catch {
212	          return [n.id, null] as const;
213	        }
214	      }),
215	    ),
216	  );
217	
218	  // "Expiring soon": due for renewal within EXPIRING_SOON_DAYS, still actually
219	  // in play (not free, not already on its way out). A server already SUSPENDED
220	  // or DELETING is already being handled by the dunning flow — surfacing it
221	  // here too would just be noise on top of its own status chip.
222	  const now = Date.now();
223	  const soonCutoff = now + EXPIRING_SOON_DAYS * 24 * 60 * 60 * 1000;
224	  const expiringSoon = servers.filter(
225	    (s) =>
226	      !s.isFree &&
227	      s.status !== "SUSPENDED" &&
228	      s.status !== "DELETING" &&
229	      s.expiresAt &&
230	      s.expiresAt.getTime() >= now &&
231	      s.expiresAt.getTime() <= soonCutoff,
232	  ).sort((a, b) => a.expiresAt!.getTime() - b.expiresAt!.getTime());
233	
234	  return (
235	    <div className="space-y-6">
236	      {anyTransitional && <AutoRefresh />}
237	      <PageHeader title="Server fleet" sub={`${total} server${total === 1 ? "" : "s"} across all clients.`} />
238	
239	      {expiringSoon.length > 0 && (
240	        <div className="rounded-xl border border-amber-500/30 bg-amber-500/[0.07] px-4 py-3">
241	          <div className="flex flex-wrap items-center gap-2 text-sm text-amber-300">
242	            <span className="font-medium">
243	              {expiringSoon.length} server{expiringSoon.length === 1 ? "" : "s"} renewing within {EXPIRING_SOON_DAYS} days
244	            </span>
245	          </div>
246	          <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-amber-300/80">
247	            {expiringSoon.slice(0, 8).map((s) => (
248	              <Link key={s.id} href={`/admin/servers/${s.id}`} className="hover:text-amber-200 hover:underline">
249	                {s.hostname} · {s.expiresAt!.toISOString().slice(0, 10)}
250	              </Link>
251	            ))}
252	            {expiringSoon.length > 8 && <span>+{expiringSoon.length - 8} more</span>}
253	          </div>
254	        </div>
255	      )}
256	
257	      {/* Status filter chips */}
258	      <StatusChips
259	        liveTotal={total}
260	        countByStatus={countByStatus}
261	        archiveCountFor={archiveCountFor}
262	        liveActive={statusFilter}
263	        active={undefined}
264	      />
265	
266	      {(() => {
267	        const columns: FleetColumn[] = [
268	          { header: "Hostname" },
269	          { header: "Owner" },
270	          { header: "Type" },
271	          { header: "Plan" },
272	          { header: "VMID" },
273	          { header: "SSH endpoint" },
274	          { header: "Node" },
275	          { header: "Region" },
276	          { header: "Provisioned" },
277	          { header: "Total spent" },
278	          { header: "Resources", className: "min-w-40" },
279	          { header: "Status" },
280	          { header: "Expires" },
281	          { header: "Actions", className: "text-right" },
282	        ];
283	
284	        const rows: FleetRow[] = servers.map((s) => {
285	          const gameFamily = s.gamePlan?.gameFamily ?? null;
286	          const planName = s.gamePlan ? s.gamePlan.name : s.plan.name;
287	          const search = [s.hostname, s.user.email, s.user.name, planName, s.node?.name, s.node ? REGION_LABELS[s.node.region] ?? s.node.region : null]
288	            .filter(Boolean)
289	            .join(" ")
290	            .toLowerCase();
291	          const spentCents = spendByServerId.get(s.id) ?? 0;
292	          return {
293	            id: s.id,
294	            search,
295	            cells: [
296	              <span key="h">
297	                <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
298	                  {s.hostname}
299	                </Link>
300	                {s.isFree && (
301	                  <span className="ml-2">
302	                    <Badge tone="green">free</Badge>
303	                  </span>
304	                )}
305	              </span>,
306	              <Link key="o" href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">
307	                {s.user.email}
308	              </Link>,
309	              <ServiceType key="type" gameFamily={gameFamily} />,
310	              <span key="p">
311	                {planName}
312	                {!s.isFree && (
313	                  <span className="text-xs text-slate-500">
314	                    {" "}
315	                    ·{" "}
316	                    {fmtMoney(s.gamePlan ? monthlyCents(s.gamePlan.priceCents, s.gamePlan.termMonths) : s.plan.priceCents)}
317	                    /mo
318	                  </span>
319	                )}
320	              </span>,
321	              <span key="v" className="font-mono text-xs">{s.vmid ?? "—"}</span>,
322	              <span key="ssh" className="font-mono text-xs">
323	                {/* The CONNECTABLE endpoint: NAT servers reach the VM through the node's
324	                    PUBLIC ip + the forwarded ssh port — never the internal 10.20.x.x
325	                    address (that's unreachable from outside the host). Show the public
326	                    endpoint like the customer dashboard does; keep the internal ip as a
327	                    muted secondary line for admin NAT debugging. */}
328	                {s.sshPort ? (
329	                  <>
330	                    <span>{`${s.node?.publicIp ?? process.env.PUBLIC_IP ?? "—"}:${s.sshPort}`}</span>
331	                    {s.ipAddress && <div className="text-slate-600">int {s.ipAddress}</div>}
332	                  </>
333	                ) : (
334	                  s.ipAddress ?? "—"
335	                )}
336	              </span>,
337	              <span key="n" className="text-xs">
338	                {s.node ? (
339	                  <Link href={`/admin/nodes/${s.node.id}`} className="hover:text-brand-300">
340	                    {s.node.name}
341	                  </Link>
342	                ) : (
343	                  "—"
344	                )}
345	              </span>,
346	              <RegionCell key="r" region={s.node?.region ?? null} />,
347	              <span key="prov" className="text-xs text-slate-400" title={s.createdAt.toISOString()}>
348	                {s.createdAt.toISOString().slice(0, 10)}
349	              </span>,
350	              <span key="spend" className="text-xs" title="Real lifetime total: order + renewals + add-ons, net of refunds — not an estimate">
351	                {spentCents > 0 ? fmtMoney(spentCents) : <span className="text-slate-600">—</span>}
352	              </span>,
353	              <span key="res">
354	                {(() => {
355	                  const live = s.vmid && s.node ? liveByNode.get(s.node.id)?.get(s.vmid) : null;
356	                  if (!live) {
357	                    return <span className="text-xs text-slate-600">{s.vmid ? "unavailable" : "—"}</span>;
358	                  }
359	                  const cpuPct = Math.round((live.cpu ?? 0) * 100);
360	                  const memRatio = live.maxmem > 0 ? live.mem / live.maxmem : 0;
361	                  return (
362	                    <div className="space-y-1.5">
363	                      <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
364	                        <span>CPU</span>
365	                        <span className="font-mono">{cpuPct}%</span>
366	                      </div>
367	                      <MeterBar value={cpuPct} max={100} color={cpuPct > 90 ? "#ef4444" : cpuPct > 75 ? "#f59e0b" : "#34d399"} />
368	                      <div className="flex items-center justify-between gap-2 text-[11px] text-slate-500">
369	                        <span>RAM</span>
370	                        <span className="font-mono">
371	                          {fmtBytes(live.mem)} / {fmtBytes(live.maxmem)}
372	                        </span>
373	                      </div>
374	                      <MeterBar
375	                        value={live.mem}
376	                        max={live.maxmem || 1}
377	                        color={memRatio > 0.9 ? "#ef4444" : memRatio > 0.75 ? "#f59e0b" : "#34d399"}
378	                      />
379	                    </div>
380	                  );
381	                })()}
382	              </span>,
383	              <StatusDot key="s" status={s.status} />,
384	              <span key="e" className="text-xs">
385	                {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
386	              </span>,
387	              <div key="a" className="flex flex-wrap items-center justify-end gap-2">
388	                {(["ERROR", "PENDING", "PROVISIONING"] as ServerStatus[]).includes(s.status) && (
389	                  <ReconcileServerButton serverId={s.id} />
390	                )}
391	                {s.status !== "DELETING" && <RebootServerButton serverId={s.id} status={s.status} />}
392	                {s.status !== "DELETING" && (
393	                  <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
394	                )}
395	              </div>,
396	            ],
397	          };
398	        });
399	
400	        return (
401	          <ServerFleetTable
402	            columns={columns}
403	            rows={rows}
404	            minWidth={1900}
405	            empty={`No servers${statusFilter ? ` in status ${statusFilter.toLowerCase()}` : " yet"}.`}
406	          />
407	        );
408	      })()}
409	
410	      <p className="text-xs text-slate-500">
411	        Provisioned is the server&apos;s real creation date. Total spent is a real historical sum — the order,
412	        every renewal and every add-on this server was actually billed, net of refunds — never an estimate off
413	        the current plan price. A dash means no billing record was found for that server (e.g. a free server).
414	      </p>
415	    </div>
416	  );
417	}
