419	/** Shared chip row for both the live fleet view and the archive views, so
420	 *  "All", every live status, and Cancelled/Expired/Deleted always sit
421	 *  together in one place regardless of which one is currently selected. */
422	function StatusChips({
423	  liveTotal,
424	  countByStatus,
425	  archiveCountFor,
426	  liveActive,
427	  active,
428	}: {
429	  liveTotal: number;
430	  countByStatus?: Map<ServerStatus, number>;
431	  archiveCountFor: (reasons: string[]) => number;
432	  liveActive: ServerStatus | undefined;
433	  active: string | undefined;
434	}) {
435	  const chip = (href: string, label: string, count: number, isActive: boolean) => (
436	    <Link
437	      key={href}
438	      href={href}
439	      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
440	        isActive
441	          ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
442	          : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
443	      }`}
