20	/**
21	 * Ledger-description prefixes whose NEGATIVE rows are money LEAVING the business
22	 * (or an accounting correction), not revenue earned.
23	 *
24	 * REAL DEFECT (2026-07-27 admin audit). Every revenue figure in the console was
25	 * `SUM(-amountCents) WHERE amountCents < 0` — "any wallet debit is revenue". Four
26	 * paths write a negative wallet row that is the opposite of revenue:
27	 *
28	 *   - `refundPayment` (lib/actions-admin-billing.ts) writes `Refund — …` with
29	 *     `amountCents: -walletDebit`. Refunding a customer $200 therefore ADDED $200
30	 *     to "Revenue · 30d", "Revenue · all time", "Lifetime revenue", the 14-day
31	 *     revenue chart, "Revenue by month" and ARPU. A bad month of refunds read as
32	 *     a record month, in the direction that hides the problem.
33	 *   - `adjustBalance` writes `Admin balance adjustment…`, which is negative when
34	 *     an operator claws back a mistaken credit — again the reversal of revenue.
35	 *   - `requestAffiliatePayout` / `adminUpdatePayout` (lib/actions-affiliate.ts)
36	 *     write `Affiliate payout …` when commission is reserved for cash-out. That
37	 *     is a cost of sale being counted as a sale.
38	 *   - `Reversed downgrade credit (resize failed)` unwinds a credit we issued.
39	 *
40	 * Matching on description is not elegant — the ledger has no `kind` column — but
41	 * it is exact for the rows that exist, it is the same technique the "Credits
42	 * issued" card already used, and `test/admin-console-guards.test.ts` enumerates
43	 * every `walletTransaction.create` description literal in the repo and fails if a
44	 * new one is not classified here. A new ledger row cannot silently join the
45	 * revenue line.
46	 */
47	export const NON_REVENUE_PREFIXES = [
48	  "Refund",
49	  "Admin balance adjustment",
50	  "Affiliate payout",
51	  "Reversed downgrade credit",
52	  "Write-off",
53	] as const;
