70	 * a debit whose description is not one of the reversals above, AND whose owner is
71	 * a revenue-counting account. Spread it into a query alongside any date range.
72	 */
73	export const REVENUE_WHERE: Prisma.WalletTransactionWhereInput = {
74	  amountCents: { lt: 0 },
75	  NOT: NON_REVENUE_PREFIXES.map((p) => ({ description: { startsWith: p } })),
76	  user: REVENUE_USER_WHERE,
77	};
