109	/**
110	 * Fetches the four admin-priced renewal inputs together, ONCE, for callers
111	 * that need to price a whole fleet (serverMonthlyCents/fleetMrrCents below).
112	 * Deliberately NOT exported from lib/renewal-charge.ts itself — that file is
113	 * imported by a CLIENT component (the deploy wizard's term cards) and stays
114	 * free of anything that touches the database; every one of these four is a
115	 * `getSettingInt` read and must stay server-only.
116	 */
117	export async function currentRenewalPrices(): Promise<RenewalPrices> {
118	  const [ipMonthlyCents, extraDiskPerGbCentsVal, backupPlusCents, annualPct] = await Promise.all([
119	    dedicatedIpMonthlyCents(),
120	    extraDiskPerGbCents(),
121	    backupPlusMonthlyCents(),
122	    annualDiscountPct(),
123	  ]);
124	  return { ipMonthlyCents, extraDiskPerGbCents: extraDiskPerGbCentsVal, backupPlusCents, annualDiscountPct: annualPct };
