127	/**
128	 * What one server actually contributes per month.
129	 *
130	 * REAL DEFECT (2026-07-27 admin audit, extended 2026-09-10). "MRR" on /admin,
131	 * /admin/subscriptions and /admin/analytics was `SUM(plan.priceCents)` over
132	 * every non-free, non-DELETING server. Four things were wrong with that, all
133	 * in the flattering direction:
134	 *
135	 *   1. GAME SERVERS. A game server carries BOTH a base `planId` and a
136	 *      `gamePlanId` and is sold at the game plan's flat price — the exact reason
137	 *      `renewNow` reads `gamePlan.priceCents` (lib/actions.ts) after billing a
138	 *      $4.99 tier at the $8.99 base rate. The dashboard still made that mistake.
139	 *   2. TERM PRICE. `plan.priceCents` is the monthly LIST price. A server bought
140	 *      on a discounted 36-month term is billed far less per month than list, so
141	 *      list-price MRR overstates committed revenue for every long-term customer.
142	 *      /admin/products already normalises its add-on MRR with a
143	 *      price-over-term division; VPS MRR did not.
144	 *   3. SUSPENDED SERVERS. The renewal sweep SKIPS suspended servers — an
145	 *      admin-suspended or abuse-suspended machine is never charged (see
146	 *      `adminSuspendServer`) — yet it counted at full price forever.
147	 *   4. ADD-ONS. Found live 2026-09-10 on a real customer: their invoice was
148	 *      $19.98 (plan $16.99 + a $2.99/mo dedicated-IP surcharge, correctly
149	 *      billed every renewal per worker/billing.ts's own sweep), but "Monthly
150	 *      spend" on their admin page showed $16.99 — this function never priced
151	 *      dedicated IP, extra disk, or the Plus backup tier at all, the exact
152	 *      "second formula" lib/renewal-charge.ts's own docstring warns never to
153	 *      write ("there is ONE renewal formula... two incidents in one day came
154	 *      from a second copy"). Now delegates to `renewalCharge` — the same
155	 *      formula worker/billing.ts's sweep actually charges from — instead of
156	 *      maintaining an independent, incomplete copy.
157	 *
158	 * Returns 0 for anything not currently billable.
159	 */
160	export function serverMonthlyCents(s: MrrServer, prices: RenewalPrices): number {
161	  if (s.isFree) return 0;
162	  // Not billed while suspended or being torn down.
163	  if (s.status === "SUSPENDED" || s.status === "DELETING") return 0;
164	  const charge = renewalCharge(s, prices);
165	  return monthlyCents(charge.netCents, charge.months);
166	}
