168	/**
169	 * A term price expressed per month. Mirrors `monthlyCents` in
170	 * components/admin/ProductTables.tsx, which has always normalised the add-on
171	 * catalogue this way; VPS pricing simply never used it.
172	 */
173	export function monthlyCents(priceCents: number, termMonths: number): number {
174	  const months = Math.max(1, termMonths || 1);
175	  return Math.round(priceCents / months);
176	}
