178	/** Sum `serverMonthlyCents` across a fleet. */
179	export function fleetMrrCents(servers: MrrServer[], prices: RenewalPrices): number {
180	  return servers.reduce((n, s) => n + serverMonthlyCents(s, prices), 0);
181	}
