213	
214	export type RevenueRange = "today" | "7d" | "14d" | "1m" | "all";
215	
216	export const REVENUE_RANGES: { key: RevenueRange; label: string }[] = [
217	  { key: "today", label: "Today" },
218	  { key: "7d", label: "7 days" },
219	  { key: "14d", label: "14 days" },
220	  { key: "1m", label: "1 month" },
221	  { key: "all", label: "All time" },
222	];
223	
224	export type RevenueSeriesResult = {
225	  series: number[];
226	  xLabels: string[];
227	  total: number;
228	  since: string;
229	  granularity: "hour" | "day" | "week" | "month";
230	};
231	
232	function utcDayKey(d: Date): string {
233	  return d.toISOString().slice(0, 10);
234	}
235	
236	/** The real first revenue record ever posted for this account (not an arbitrary window). */
237	async function firstRevenueDate(): Promise<Date> {
238	  const first = await db.walletTransaction.findFirst({
239	    where: REVENUE_WHERE,
240	    orderBy: { createdAt: "asc" },
241	    select: { createdAt: true },
242	  });
243	  return first?.createdAt ?? new Date();
244	}
245	
246	/** Start-of-bucket Date objects covering `[since, now]` at the given granularity. */
247	function bucketStarts(since: Date, now: Date, granularity: RevenueSeriesResult["granularity"]): Date[] {
248	  if (granularity === "month") {
249	    const starts: Date[] = [];
250	    const cur = new Date(Date.UTC(since.getUTCFullYear(), since.getUTCMonth(), 1));
251	    const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
252	    while (cur.getTime() <= end.getTime()) {
253	      starts.push(new Date(cur));
254	      cur.setUTCMonth(cur.getUTCMonth() + 1);
255	    }
256	    return starts;
257	  }
258	  const stepMs = granularity === "hour" ? 3600_000 : granularity === "day" ? 86400_000 : 7 * 86400_000;
259	  const starts: Date[] = [];
260	  let cur = new Date(since);
261	  while (cur.getTime() <= now.getTime()) {
262	    starts.push(new Date(cur));
263	    cur = new Date(cur.getTime() + stepMs);
264	  }
265	  if (starts.length === 0) starts.push(new Date(since));
266	  return starts;
267	}
268	
269	/** Index of the last bucket whose start is `<= d` (bucket starts are sorted ascending). */
270	function bucketIndexFor(starts: Date[], d: Date): number {
271	  let lo = 0;
272	  let hi = starts.length - 1;
273	  let ans = 0;
274	  while (lo <= hi) {
275	    const mid = (lo + hi) >> 1;
276	    if (starts[mid].getTime() <= d.getTime()) {
277	      ans = mid;
278	      lo = mid + 1;
279	    } else {
280	      hi = mid - 1;
281	    }
282	  }
283	  return ans;
284	}
285	
286	function bucketLabel(d: Date, granularity: RevenueSeriesResult["granularity"]): string {
287	  if (granularity === "hour") return `${String(d.getUTCHours()).padStart(2, "0")}:00`;
288	  if (granularity === "month") return d.toISOString().slice(0, 7);
289	  return utcDayKey(d).slice(5); // MM-DD
290	}
291	
292	/**
293	 * Real revenue aggregation for the Operations Overview "Revenue" card, generalized
294	 * from the original hardcoded 14-day window to accept any `RevenueRange`. Every
295	 * range does a fresh DB query scoped to its own window — this is NOT the old
296	 * fixed 14-day dataset sliced client-side, so "Today" and "All time" both reflect
297	 * transactions the 14-day query would never have fetched in the first place.
298	 *
299	 * Bucketing granularity adapts to the span so the chart stays readable: hourly
300	 * for "Today", daily up to ~90 days, weekly up to ~18 months, monthly beyond
301	 * that (relevant mainly to "All time" on an older account).
302	 *
303	 * Same revenue definition as everywhere else in the console: `REVENUE_WHERE`
304	 * (orders/renewals/add-ons, refunds and affiliate payouts excluded) scoped to
305	 * revenue-counting accounts.
306	 */
307	export async function revenueSeriesForRange(range: RevenueRange): Promise<RevenueSeriesResult> {
308	  const now = new Date();
309	  let since: Date;
310	  switch (range) {
311	    case "today": {
312	      since = new Date(now);
313	      since.setUTCHours(0, 0, 0, 0);
314	      break;
315	    }
316	    case "7d":
317	      since = new Date(now.getTime() - 7 * 86400_000);
318	      break;
319	    case "14d":
320	      since = new Date(now.getTime() - 14 * 86400_000);
321	      break;
322	    case "1m":
323	      since = new Date(now.getTime() - 30 * 86400_000);
324	      break;
325	    case "all":
326	    default:
327	      since = await firstRevenueDate();
328	      break;
329	  }
330	
331	  const spanDays = Math.max(0, (now.getTime() - since.getTime()) / 86400_000);
332	  const granularity: RevenueSeriesResult["granularity"] =
333	    range === "today" ? "hour" : spanDays <= 90 ? "day" : spanDays <= 548 ? "week" : "month";
334	
335	  // Real DB aggregation scoped to this range's own window — every toggle re-queries
336	  // WalletTransaction, it never slices a dataset fetched for a different range.
337	  const tx = await db.walletTransaction.findMany({
338	    where: { ...REVENUE_WHERE, createdAt: { gte: since } },
339	    select: { amountCents: true, createdAt: true },
340	  });
341	
342	  const starts = bucketStarts(since, now, granularity);
343	  const totals = new Array(starts.length).fill(0);
344	  for (const t of tx) {
345	    totals[bucketIndexFor(starts, t.createdAt)] += Math.abs(t.amountCents);
346	  }
347	
348	  const series = totals.map((c) => c / 100);
349	  const total = series.reduce((a, b) => a + b, 0);
350	  const labels = starts.map((d) => bucketLabel(d, granularity));
351	  // First / middle / last labels only — matches the original 14-day chart's
352	  // 3-tick x-axis regardless of how many buckets this range produces.
353	  const xLabels =
354	    labels.length <= 1
355	      ? labels
356	      : [labels[0], labels[Math.floor((labels.length - 1) / 2)], labels[labels.length - 1]];
357	
358	  return { series, xLabels, total, since: since.toISOString(), granularity };
359	}
