async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

}

export default async function DashboardPage() {
  const user = await requireUser();
  const monthAgo = new Date(Date.now() - 30 * 86_400_000);

  const [servers, hostingCount, hasFree, auditLogs, openTickets, newThisMonth, plans, gamePlans, hostingPlans, emailPlans] =
    await Promise.all([
      db.server.findMany({
        where: { userId: user.id },
        // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs; `node`
        // carries the region the Location column shows.
        // `portForwards` joins `dedicatedIp`/`node` as what connectAddress needs
        // to work out the address a customer can actually reach the box on.
        include: {
          plan: true, osTemplate: true, gamePlan: true, dedicatedIp: true, node: true,
          portForwards: { select: { publicPort: true, guestPort: true } },
        },
        orderBy: { createdAt: "desc" },
      }),
      /* This dashboard's own "Total Services" stat and its widget's per-type
         tab counts used to come from `servers.length`/`rows` alone — which
         only ever holds VPS + game-server rows (this same `db.server`
         query). Shared Hosting and a claimed free server are real services
         (lib/nx/services.ts's `listServices()`, which /dashboard/services
         correctly uses, counts them) but live in different tables
         (HostingAccount, FreeMinecraftServer) this page never queried, so
         they silently read as 0 here — the exact "undercounts your own
         services" bug audited today. Two cheap counts, not a full re-fetch
         of listServices()'s richer rows (this page's own `rows` table is
         VPS/game-only by design, showing recent server activity — these are
         only for getting the STAT AND TAB NUMBERS honest). */
      db.hostingAccount.count({ where: { userId: user.id } }),
      db.freeMinecraftServer.findUnique({ where: { userId: user.id }, select: { id: true } }),
      db.auditLog.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 8 }),
      db.ticket.count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }),
      db.server.count({ where: { userId: user.id, createdAt: { gte: monthAgo } } }),
      db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
      db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
      db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
      /* `active: true` matters here specifically: staging (and, presumably,
         any long-lived install) accumulates retired $0 plan rows — this fork
         has 5 of them ("Unlimited", a few bundled-hosting-email leftovers,
         "Free Domain Inbox") — and a query with no active filter, sorted
         priceCents ascending, picks one of those up first. That is the exact
         "Business Email $0.00/mo" bug: real Starter is $1.99, not $0. */
      db.emailPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
    ]);

  const uptime = await uptimeFor(servers.map((s) => s.id));
  // The play-subdomain base is an admin setting shared by free and paid game
  // servers, so the connect address stays right if the owner ever moves it.
  const gameBase = await gameSubdomainBase();

  /* Was anything removed in the window? If so, last month's estate cannot be
     reconstructed from what is still in the table, and any delta computed from
     the survivors could only ever point up. Better no delta than a number that
     is wrong in one direction by construction. */
  const removals = await db.auditLog.count({
    where: {
      userId: user.id,
      createdAt: { gte: monthAgo },
      OR: [{ action: { contains: "delete" } }, { action: { contains: "terminate" } }, { action: { contains: "cancel" } }],
    },
  });

  // "Monthly spend" is priced through `renewalCharge` — the single function
  // worker/billing.ts, the saved-card path and the "Renew now" button all charge
  // through (lib/renewal-charge.ts). Summing `plan.priceCents` instead is a
  // SECOND formula and a different number: it bills a $4.99 game server at its
  // $8.99 base VPS plan and counts nothing for purchased extra disk or a
  // dedicated IP the customer really does pay for every cycle.
  const paid = servers.filter((s) => !s.isFree && s.status !== "DELETING");
  const spendTaxRatePercent = (await taxContextForUser(user)).ratePercent;
  const spendPrices =
    paid.length > 0
      ? {
          ipMonthlyCents: await dedicatedIpMonthlyCents(),
          extraDiskPerGbCents: await extraDiskPerGbCents(),
          backupPlusCents: await backupPlusMonthlyCents(),
          annualDiscountPct: await annualDiscountPct(),
          taxRatePercent: spendTaxRatePercent,
        }
      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent: spendTaxRatePercent };
  const monthlySpendCents = paid.reduce((sum, s) => {
    const charge = renewalCharge(s, spendPrices);
    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
  }, 0);

  /* Last month's recurring cost, priced the same way through `renewalCharge` —
     the estate as it stood 30 days ago is the servers that already existed then.
     Only trustworthy when nothing was removed since (see `removals`). */
  const priorPaid = paid.filter((s) => s.createdAt < monthAgo);
  const priorSpendCents = priorPaid.reduce((sum, s) => {
    const charge = renewalCharge(s, spendPrices);
    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));

  };
}


