): FleetTag[] {
  const tags: FleetTag[] = [];
  const nowMs = opts.now.getTime();

  if (s.grandfatheredRenewalCents != null) {
    tags.push({ key: "grandfathered", tone: "brand", label: "Grandfathered" });
  }
  if (s.extraDiskGB > 0) {
    tags.push({ key: "disk", tone: "slate", label: `+${s.extraDiskGB} GB disk` });
  }
  if (s.backupTier === "PLUS") {
    tags.push({ key: "backup", tone: "slate", label: "Backup Plus" });
  }
  // Billable IP only (dedicatedIp present AND wantsDedicatedIp) — matches
  // renewalCharge's own `dedicatedIpBillable` gate exactly (lib/renewal-charge.ts),
  // so this tag never claims a surcharge for a free platform-default IP perk.
  if (s.dedicatedIp && s.wantsDedicatedIp) {
    tags.push({ key: "ip", tone: "slate", label: "Dedicated IP" });
  }

  // OVERDUE. Two real states worker/billing.ts itself already distinguishes —
  // lifted directly from its own queries, not reinvented:
  //  1. Suspended for nonpayment: exactly `terminateOverdue`'s own where-clause
  //     (status SUSPENDED, suspendReason UNPAID) — worker/billing.ts's one real
  //     definition of "overdue and suspended for it".
  //  2. Expired but not yet suspended (still mid-dunning or awaiting the sweep's
  //     first attempt): exactly `dueServers()`'s own where-clause (expired,
  //     status RUNNING/STOPPED) — the sweep's own definition of "due".
  const suspendedUnpaid = s.status === "SUSPENDED" && s.suspendReason === "UNPAID";
  const expiredNotYetSuspended =
    !s.isFree && s.expiresAt != null && s.expiresAt.getTime() < nowMs && (s.status === "RUNNING" || s.status === "STOPPED");
  const overdue = suspendedUnpaid || expiredNotYetSuspended;

  // DELETING SOON. Only the suspended-unpaid branch of "overdue" ever gets
  // terminated — mirrors terminateOverdue's own `warnAt`/`terminateAt` window
  // exactly (lib/dunning-config.ts's `dunningConfig()`, the same function the
  // real sweep calls). Strictly a subset of `overdue`, so it REPLACES the
  // "Overdue" tag rather than adding a second red pill that says less.
  let deletingSoon = false;
  let terminateAtDate: Date | null = null;
  if (suspendedUnpaid && s.expiresAt && opts.dunning && opts.dunning.autoSuspend) {
    const DAY_MS = 86_400_000;
    const warnAt = s.expiresAt.getTime() + opts.dunning.warnDays * DAY_MS;
    terminateAtDate = new Date(s.expiresAt.getTime() + opts.dunning.terminateDays * DAY_MS);
    if (nowMs >= warnAt) deletingSoon = true;
  }

  if (deletingSoon) {
    tags.push({
      key: "deleting",
      tone: "red",
      label: "Deleting soon",
      title: terminateAtDate
        ? `Unpaid since ${s.expiresAt!.toISOString().slice(0, 10)} — scheduled for deletion around ${terminateAtDate.toISOString().slice(0, 10)} if it stays unpaid`
        : undefined,
    });
  } else if (overdue) {
    tags.push({ key: "overdue", tone: "red", label: "Overdue" });
  } else {
    // RENEWING SOON — only meaningful when not already overdue/suspended/deleting
    // (an overdue server is not "renewing soon", it already failed to renew).
    // Mirrors app/admin/servers/page.tsx's own "expiring soon" alert filter.
    const renewingSoon =
      !s.isFree &&
      s.status !== "SUSPENDED" &&
      s.status !== "DELETING" &&
      s.expiresAt != null &&
      s.expiresAt.getTime() >= nowMs &&
      s.expiresAt.getTime() <= nowMs + opts.renewingSoonWindowMs;
    if (renewingSoon) tags.push({ key: "renewing_soon", tone: "amber", label: "Renewing soon" });
  }

  return tags;
}

