1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { readFileSync } from "node:fs";
4	import { join } from "node:path";
5	import { DUNNING_RETRY_ATTEMPTS, emails } from "../lib/mailer.ts";
6	
7	/**
8	 * REAL INCIDENT / REAL RISK — the dunning ladder (audit gaps #3 and #9, QA P1-5).
9	 *
10	 * Before the card engine existed, a customer with a perfectly good card was
11	 * suspended the moment their wallet emptied, and was told about it with nothing
12	 * but a bell icon in a portal they had stopped visiting. The replacement retries
13	 * the card on days 1, 3 and 5 past expiry, emails at each step, and suspends only
14	 * after every attempt is spent PLUS one clear day after the final notice.
15	 *
16	 * Two things can silently break that promise:
17	 *   (a) the schedule the worker runs drifting from the number the email quotes
18	 *       ("we'll try 2 more times" when only one attempt is left), and
19	 *   (b) a suspension landing on or before the day of the final notice, so the
20	 *       warning arrives after the server is already down.
21	 *
22	 * The worker derives the whole ladder from `DUNNING_RETRY_ATTEMPTS` in
23	 * lib/mailer.ts — the same constant the email copy subtracts from — precisely so
24	 * they cannot drift. That derivation is module-private in `worker/billing.ts`
25	 * (and duplicated by hand in `lib/actions-settings.ts`), so this file reads the
26	 * constants out of the source and holds them against the imported constant and
27	 * against the actual rendered email text.
28	 *
29	 * Deterministic: everything is arithmetic on day offsets. No clock, no DB, no
30	 * Stripe — the email builders are pure and send nothing.
31	 */
32	
33	const REPO = join(__dirname, "..");
34	/** Sources are read with whitespace collapsed, so reformatting is not a failure. */
35	const readNormalized = (rel: string) => readFileSync(join(REPO, rel), "utf8").replace(/\s+/g, " ");
36	const BILLING_SRC = readNormalized("worker/billing.ts");
37	const SETTINGS_SRC = readNormalized("lib/actions-settings.ts");
38	
39	function sourceNumber(src: string, re: RegExp, what: string): number {
40	  const m = re.exec(src);
41	  assert.ok(m, `${what}: ${re} not found — the dunning ladder was rewritten, re-read it and update this test`);
42	  return Number(m![1]);
43	}
44	
45	/* ---- the ladder, read from worker/billing.ts ---------------------------- */
46	
47	/** `const retryDayFor = (retry: number) => 2 * retry - 1;` */
48	const RETRY_DAY_MULT = sourceNumber(BILLING_SRC, /const retryDayFor = \(retry: number\) => (\d+) \* retry - \d+;/, "retryDayFor multiplier");
49	const RETRY_DAY_OFFSET = sourceNumber(BILLING_SRC, /const retryDayFor = \(retry: number\) => \d+ \* retry - (\d+);/, "retryDayFor offset");
50	const retryDayFor = (retry: number) => RETRY_DAY_MULT * retry - RETRY_DAY_OFFSET;

const EXHAUSTED_OFFSET = sourceNumber(BILLING_SRC, /const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS \+ (\d+);/, "DUNNING_EXHAUSTED");
/** `const SUSPEND_SLIP_CAP_DAYS = 4;` */
const SUSPEND_SLIP_CAP_DAYS = sourceNumber(BILLING_SRC, /const SUSPEND_SLIP_CAP_DAYS = (\d+);/, "SUSPEND_SLIP_CAP_DAYS");
/** `const MIN_RETRY_GAP_MS = 20 * 3600_000;` */
const MIN_RETRY_GAP_HOURS = sourceNumber(BILLING_SRC, /const MIN_RETRY_GAP_MS = (\d+) \* 3600_000;/, "MIN_RETRY_GAP_MS");

/** Days past expiry on which the worker retries the card. */
const RETRY_DAYS = Array.from({ length: DUNNING_RETRY_ATTEMPTS }, (_, i) => retryDayFor(i + 1));
const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
const CARD_SUSPEND_DAY = LAST_RETRY_DAY + SUSPEND_DAYS_AFTER_LAST_RETRY;
const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + EXHAUSTED_OFFSET;

test("the ladder is the documented day-1/3/5 schedule", () => {
  assert.equal(DUNNING_RETRY_ATTEMPTS, 3);
  assert.deepEqual(RETRY_DAYS, [1, 3, 5]);
  assert.equal(LAST_RETRY_DAY, 5);
  assert.equal(CARD_SUSPEND_DAY, 6);
  assert.equal(DUNNING_EXHAUSTED, 4, "the expiry-day attempt plus three retries");
});

test("the schedule is DERIVED from DUNNING_RETRY_ATTEMPTS, not hardcoded beside it", () => {
  // The one line that keeps the worker's behaviour and the email's promise tied
  // together. A literal here is how "we'll try 3 more times" starts outliving the
  // third retry.
  assert.ok(
    BILLING_SRC.includes("const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);"),
    "the last retry day must be derived from the constant the emails quote",
  );
  assert.ok(BILLING_SRC.includes("const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;"));
  assert.ok(
    BILLING_SRC.includes('import { DUNNING_RETRY_ATTEMPTS, emails, sendMail } from "../lib/mailer";'),
    "one constant, imported — not a second copy of the number",
  );
});

test("one retry per attempt, strictly increasing, never before expiry", () => {
  assert.equal(RETRY_DAYS.length, DUNNING_RETRY_ATTEMPTS, "as many retry slots as attempts promised");
  assert.equal(new Set(RETRY_DAYS).size, RETRY_DAYS.length, "no two retries on the same day");
  for (let i = 0; i < RETRY_DAYS.length; i++) {
    assert.ok(RETRY_DAYS[i] >= 1, `retry ${i + 1} must land at least a day past expiry, got ${RETRY_DAYS[i]}`);
    if (i > 0) assert.ok(RETRY_DAYS[i] > RETRY_DAYS[i - 1], "the ladder must move forward");
  }
});

test("suspension never precedes the final notice", () => {
  // The final notice is sent when the LAST retry fails, i.e. on LAST_RETRY_DAY.
