 * no awareness of add-ons or a per-server grandfathered rate.
 *
 * `serverFleetPriceCents` is a thin wrapper over `renewalCharge` — the same
 * pricing formula worker/billing.ts, the saved-card path and "Renew now" all
 * charge through — so the grandfather-survives-a-price-rise and
 * unaffected-when-unset guarantees are already proven at the `renewalCharge`
 * level in test/money-core-guards.test.ts. What's specific to THIS file is:
 * the fleet list actually calls through to that guarantee, includes add-ons,
 * and (deliberately, unlike MRR's serverMonthlyCents) does not zero out for a
 * suspended row — plus the tag logic, which is new.
 */

const PRICES: RenewalPrices = { ipMonthlyCents: 299, extraDiskPerGbCents: 100, backupPlusCents: 199, annualDiscountPct: 0 };

function vps(overrides: Partial<PricedServer> = {}): PricedServer {
  return {
    termMonths: 1,
    extraDiskGB: 0,
    plan: { name: "Starter", priceCents: 899 },
    gamePlan: null,
    dedicatedIp: null,
    wantsDedicatedIp: false,
    backupTier: "FREE",
    ...overrides,
  };
}

test("serverFleetPriceCents: a grandfathered server shows its locked price, not the live plan price", () => {
  const s = vps({ plan: { name: "Starter", priceCents: 1619 }, grandfatheredRenewalCents: 899 });
  assert.equal(serverFleetPriceCents(s, PRICES), 899, "must show the frozen rate, not the raised live price");
});

test("serverFleetPriceCents: a non-grandfathered server is completely unaffected", () => {
  const s = vps({ plan: { name: "Starter", priceCents: 899 } });
  assert.equal(serverFleetPriceCents(s, PRICES), 899);
});

test("serverFleetPriceCents: the locked price survives whatever the live plan does later, alongside add-ons", () => {
  // The live plan price triples AND the customer has real add-ons — the locked
  // base must still win, and the add-on lines must still be added on top of it,
  // exactly like renewalCharge composes them for every other caller.
  const s = vps({
    plan: { name: "Starter", priceCents: 2699 }, // tripled since sale
    extraDiskGB: 20,
    backupTier: "PLUS",
    dedicatedIp: { id: "ip1" },
    wantsDedicatedIp: true,
    grandfatheredRenewalCents: 899,
  });
  const expected = 899 + 20 * 100 + 199 + 299; // locked base + disk + backup + IP
  assert.equal(serverFleetPriceCents(s, PRICES), expected);
});

test("serverFleetPriceCents: a free platform-default IP is never billed, grandfathered or not", () => {
  const s = vps({ dedicatedIp: { id: "ip1" }, wantsDedicatedIp: false, grandfatheredRenewalCents: 899 });
  assert.equal(serverFleetPriceCents(s, PRICES), 899);
});

test("serverFleetPriceCents: unlike MRR's serverMonthlyCents, a suspended row still shows its real price", () => {
  // MRR correctly zeroes a suspended server (it isn't being collected right
  // now). The fleet PRICE column is a different question — "what does this
  // server cost" — and must keep showing the real number so it can sit next to
  // the "Overdue" tag instead of a misleading $0.00.
  const s = vps({ plan: { name: "Starter", priceCents: 899 } });
  assert.equal(serverFleetPriceCents(s, PRICES), 899);
});

/* ------------------------------------------------------------------ *
 * Tags
 * ------------------------------------------------------------------ */

const DUNNING: DunningConfig = { graceDays: 3, warnDays: 7, terminateDays: 14, autoSuspend: true };
const DAY = 86_400_000;
const NOW = new Date("2026-09-25T00:00:00.000Z");

function server(overrides: Partial<FleetTagServer> = {}): FleetTagServer {
  return {
    status: "RUNNING",
    isFree: false,
    expiresAt: null,
    suspendReason: null,
    grandfatheredRenewalCents: null,
    extraDiskGB: 0,
    backupTier: "FREE",
    wantsDedicatedIp: false,
    dedicatedIp: null,
    ...overrides,
  };
}

const tagKeys = (s: FleetTagServer, opts: { dunning?: DunningConfig | null } = {}) =>
  serverFleetTags(s, { now: NOW, renewingSoonWindowMs: 5 * DAY, dunning: opts.dunning ?? null }).map((t) => t.key);

test("tags: Grandfathered shows only when the locked field is set", () => {
  assert.deepEqual(tagKeys(server({ grandfatheredRenewalCents: 899 })), ["grandfathered"]);
  assert.deepEqual(tagKeys(server()), []);
});

test("tags: one add-on tag per real add-on, derived from real fields", () => {
  assert.deepEqual(tagKeys(server({ extraDiskGB: 20 })), ["disk"]);
  assert.deepEqual(tagKeys(server({ backupTier: "PLUS" })), ["backup"]);
  assert.deepEqual(tagKeys(server({ dedicatedIp: { id: "ip1" }, wantsDedicatedIp: true })), ["ip"]);
  // A free platform-default IP (dedicatedIp present, never opted into paying for
  // it) is not a billed add-on and must not be tagged as one.
  assert.deepEqual(tagKeys(server({ dedicatedIp: { id: "ip1" }, wantsDedicatedIp: false })), []);
  // All three at once, in a stable order.
  assert.deepEqual(
    tagKeys(server({ extraDiskGB: 10, backupTier: "PLUS", dedicatedIp: { id: "ip1" }, wantsDedicatedIp: true })),
    ["disk", "backup", "ip"],
  );
});

test("tags: Renewing soon fires only inside the window, for a live, non-suspended server", () => {
  const soon = new Date(NOW.getTime() + 2 * DAY);
  assert.deepEqual(tagKeys(server({ expiresAt: soon })), ["renewing_soon"]);

  const far = new Date(NOW.getTime() + 30 * DAY);
  assert.deepEqual(tagKeys(server({ expiresAt: far })), []);

  // A free server never renews — no tag even with a (nonsensical) near expiresAt.
  assert.deepEqual(tagKeys(server({ isFree: true, expiresAt: soon })), []);
});

test("tags: Overdue — suspended for nonpayment (worker/billing.ts terminateOverdue's own definition)", () => {
  const s = server({ status: "SUSPENDED", suspendReason: "UNPAID", expiresAt: new Date(NOW.getTime() - 5 * DAY) });
  assert.deepEqual(tagKeys(s), ["overdue"]);
});

test("tags: an admin/abuse suspension (suspendReason not UNPAID) is never tagged Overdue", () => {
  // Matches worker/billing.ts's own terminateOverdue guard: a suspension for a
  // reason OTHER than nonpayment must never be treated as a billing problem.
  const abuse = server({ status: "SUSPENDED", suspendReason: "ABUSE", expiresAt: new Date(NOW.getTime() - 5 * DAY) });
  assert.deepEqual(tagKeys(abuse), []);
  const legacyNullReason = server({ status: "SUSPENDED", suspendReason: null, expiresAt: new Date(NOW.getTime() - 5 * DAY) });
  assert.deepEqual(tagKeys(legacyNullReason), []);
});

test("tags: Overdue — expired but not yet suspended (worker/billing.ts dueServers()'s own definition)", () => {
  const s = server({ status: "RUNNING", expiresAt: new Date(NOW.getTime() - 1 * DAY) });
  assert.deepEqual(tagKeys(s), ["overdue"]);
  const stopped = server({ status: "STOPPED", expiresAt: new Date(NOW.getTime() - 1 * DAY) });
  assert.deepEqual(tagKeys(stopped), ["overdue"]);
});

test("tags: Deleting soon replaces Overdue once past the real warn window, and matches terminateOverdue's math", () => {
  // Suspended 8 days ago; dunning.warnDays=7 means the warn window opened
  // yesterday — this is exactly the boundary terminateOverdue's own `warnAt`
  // check uses (`now.getTime() >= warnAt`).
  const expiresAt = new Date(NOW.getTime() - 8 * DAY);
  const s = server({ status: "SUSPENDED", suspendReason: "UNPAID", expiresAt });
  const tags = serverFleetTags(s, { now: NOW, renewingSoonWindowMs: 5 * DAY, dunning: DUNNING });
  assert.deepEqual(tags.map((t) => t.key), ["deleting"]);
  assert.ok(tags[0].title?.includes("scheduled for deletion"));
});

test("tags: Overdue (not Deleting soon) before the warn window opens", () => {
  const expiresAt = new Date(NOW.getTime() - 4 * DAY); // grace(3) < 4 < warn(7)
  const s = server({ status: "SUSPENDED", suspendReason: "UNPAID", expiresAt });
  assert.deepEqual(tagKeys(s, { dunning: DUNNING }), ["overdue"]);
});

test("tags: Deleting soon never fires without a real dunning config, or with auto-suspend off", () => {
  const expiresAt = new Date(NOW.getTime() - 20 * DAY); // well past any real warn window
  const s = server({ status: "SUSPENDED", suspendReason: "UNPAID", expiresAt });
  assert.deepEqual(tagKeys(s, { dunning: null }), ["overdue"], "no dunning config fetched — fall back to Overdue");
  assert.deepEqual(
    tagKeys(s, { dunning: { ...DUNNING, autoSuspend: false } }),
    ["overdue"],
    "admin kill switch off — nothing is actually being terminated, so don't claim it is",
  );
});

test("tags: Grandfathered and add-on tags compose with a lifecycle tag", () => {
  const s = server({
    grandfatheredRenewalCents: 899,
    extraDiskGB: 10,
    status: "SUSPENDED",
    suspendReason: "UNPAID",
    expiresAt: new Date(NOW.getTime() - 5 * DAY),
  });
  assert.deepEqual(tagKeys(s, { dunning: DUNNING }), ["grandfathered", "disk", "overdue"]);
});

