test("renewNow actually wires the frozen rates in, not just renewalCharge in the abstract", () => {
  // REAL BUG found 2026-09-25 auditing the grandfather program end to end.
  // Every OTHER renewalCharge caller (the automatic sweep in worker/billing.ts,
  // the saved-card path in lib/actions-payment-method.ts, the dashboard's own
  // spend figures) passes the raw Server row straight through, so
  // `grandfatheredRenewalCents`/`annualDiscountPct` ride along for free as
  // scalar columns. `renewNow` is the one caller that builds a FRESH object
  // (it swaps in a just-fetched `plan`/`gamePlan`) and had silently dropped
  // both — so a server with a locked rate that no longer matches its live
  // plan/game-plan price (checked live: several real production servers are in
  // exactly that state right now) would have been charged the LIVE price the
  // moment its owner clicked "Renew now" themselves, instead of the frozen
  // rate the automatic sweep would honor. Exactly the failure shape
  // lib/renewal-quote.ts's own docstring warns about: not a wrong formula, a
  // caller quietly starving the right one of an input it needs.
  const actionsSrc = code("../lib/actions.ts");
  const fnStart = actionsSrc.indexOf("export async function renewNow(");
  assert.ok(fnStart >= 0, "renewNow not found in lib/actions.ts — re-read it and update this test");
  const fnEnd = actionsSrc.indexOf("export async function adminExtendServer", fnStart);
  assert.ok(fnEnd > fnStart, "could not isolate the end of renewNow — re-read lib/actions.ts and update the markers");
  const renewNowSrc = actionsSrc.slice(fnStart, fnEnd);
  assert.ok(
    renewNowSrc.includes("grandfatheredRenewalCents: server.grandfatheredRenewalCents"),
    "renewNow must pass the server's own frozen grandfathered rate into renewalQuote",
  );
  assert.ok(
    renewNowSrc.includes("annualDiscountPct: server.annualDiscountPct"),
    "renewNow must pass the server's own frozen annual-discount rate into renewalQuote",
  );
});

