// actually charge, for a handful of real servers spanning every add-on
// combination. No writes anywhere.
import { db } from "./lib/db";
import { currentRenewalPrices } from "./lib/admin-metrics";
import { serverFleetPriceCents, serverFleetTags } from "./lib/admin-fleet";
import { renewalCharge } from "./lib/renewal-charge";
import { dunningConfig } from "./lib/dunning-config";

async function main() {
  const ids = [
    "cmtem49d200b7hlylo2hmcebh", // darkeden-guard-sg — the exact server named in the task
    "cmsc9l72y000ghl7iyd87u5ja", // studionexis-soul — 36mo term, legacy (no frozen annualDiscountPct), billable IP + disk
    "cmt9yxvnc0054hlrxafzd6asf", // pslgaming — billable IP, grandfathered
    "cmt9ss7ln000xhlrx0gch9fcx", // terraria-i2ydef — game server, grandfathered
    "cmu9o3e830duahl79l1h2efr2", // minecraft-qj4rxt — game server, grandfathered close to live price
  ];

  const prices = await currentRenewalPrices();
  console.log("Live renewal prices used:", prices);

  const servers = await db.server.findMany({
    where: { id: { in: ids } },
    include: { plan: true, gamePlan: true, dedicatedIp: { select: { id: true } } },
  });

  for (const s of servers) {
    const fleetPrice = serverFleetPriceCents(s as any, prices);
    const charge = renewalCharge(s as any, prices);
    const tags = serverFleetTags(s as any, { now: new Date(), renewingSoonWindowMs: 5 * 86400_000, dunning: null });
    console.log(`\n${s.hostname} (${s.id})`);
    console.log(
      `  isGame=${!!s.gamePlan} termMonths=${s.termMonths} extraDiskGB=${s.extraDiskGB} backupTier=${s.backupTier} wantsDedicatedIp=${s.wantsDedicatedIp} hasIp=${!!s.dedicatedIp}`,
    );
    console.log(
      `  plan.priceCents=${s.plan.priceCents} gamePlan.priceCents=${s.gamePlan?.priceCents ?? "n/a"} grandfatheredRenewalCents=${s.grandfatheredRenewalCents} annualDiscountPct(frozen)=${s.annualDiscountPct}`,
    );
    console.log(`  renewalCharge => months=${charge.months} netCents=${charge.netCents} totalCents=${charge.totalCents} label=${charge.label}`);
    console.log(`  fleet list price column would show: $${(fleetPrice / 100).toFixed(2)}/mo`);
    console.log(`  tags: ${tags.map((t) => t.label).join(", ") || "(none)"}`);
  }

  const cfg = await dunningConfig();
  console.log("\nReal dunningConfig() right now:", cfg);

  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

